grid[-1].append(9)
from collections import deque
h,w=len(grid),len(grid[0])
seen=set()
q=deque()
for r in range(h):
 for c in range(w):
  if r in (0,h-1) or c in (0,w-1):
   if grid[r][c]==9 and (r,c) not in seen: seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<h and 0<=nc<w and grid[nr][nc]==9 and (nr,nc) not in seen:
   seen.add((nr,nc));q.append((nr,nc))
holes=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==9 and (r,c) not in seen]
len(holes), holes
